#include <stdbool.h>
#include <stddef.h>
#include <stdio.h>

static bool has_duplicate(const int values[], size_t count,
                          size_t *comparisons)
{
    if (values == NULL || comparisons == NULL) return false;

    *comparisons = 0U;
    for (size_t i = 0U; i < count; ++i) {
        for (size_t j = i + 1U; j < count; ++j) {
            ++(*comparisons);
            if (values[i] == values[j]) return true;
        }
    }
    return false;
}

static bool contains_value(const int values[], size_t count, int target,
                           size_t *comparisons)
{
    if (values == NULL || comparisons == NULL) return false;

    *comparisons = 0U;
    for (size_t i = 0U; i < count; ++i) {
        ++(*comparisons);
        if (values[i] == target) return true;
    }
    return false;
}

int main(void)
{
    const int values[] = { 4, 8, 2, 9, 5, 7 };
    const size_t count = sizeof values / sizeof values[0];
    size_t duplicate_checks = 0U;
    size_t search_checks = 0U;

    bool duplicate = has_duplicate(values, count, &duplicate_checks);
    bool found = contains_value(values, count, 7, &search_checks);

    printf("Duplicate present: %s (%zu comparisons)\n",
           duplicate ? "yes" : "no", duplicate_checks);
    printf("Target found: %s (%zu comparisons)\n",
           found ? "yes" : "no", search_checks);
    printf("Maximum pair checks for %zu values: %zu\n",
           count, count * (count - 1U) / 2U);
    return 0;
}

#include <stdbool.h>
#include <stddef.h>
#include <stdio.h>

static bool binary_search_iterative(const int values[], size_t count,
                                    int target, size_t *steps)
{
    size_t low = 0U;
    size_t high = count;

    *steps = 0U;
    while (low < high) {
        size_t middle = low + (high - low) / 2U;
        ++(*steps);

        if (values[middle] == target) return true;
        if (values[middle] < target) {
            low = middle + 1U;
        } else {
            high = middle;
        }
    }
    return false;
}

static bool binary_search_recursive_range(const int values[],
                                          size_t low, size_t high,
                                          int target, size_t *steps)
{
    if (low >= high) return false;

    size_t middle = low + (high - low) / 2U;
    ++(*steps);

    if (values[middle] == target) return true;
    if (values[middle] < target) {
        return binary_search_recursive_range(
            values, middle + 1U, high, target, steps);
    }
    return binary_search_recursive_range(
        values, low, middle, target, steps);
}

static bool binary_search_recursive(const int values[], size_t count,
                                    int target, size_t *steps)
{
    *steps = 0U;
    return binary_search_recursive_range(values, 0U, count, target, steps);
}

int main(void)
{
    const int sorted[] = { 2, 5, 8, 12, 16, 23, 38, 56, 72, 91, 105 };
    const size_t count = sizeof sorted / sizeof sorted[0];
    size_t iterative_steps = 0U;
    size_t recursive_steps = 0U;

    bool iterative_found = binary_search_iterative(
        sorted, count, 56, &iterative_steps);
    bool recursive_found = binary_search_recursive(
        sorted, count, 56, &recursive_steps);

    printf("Iterative: %s in %zu steps\n",
           iterative_found ? "found" : "not found", iterative_steps);
    printf("Recursive: %s in %zu steps\n",
           recursive_found ? "found" : "not found", recursive_steps);
    return 0;
}
